"use client";

import type { ReactNode } from "react";

import { mixOklch, useFramecnTheme } from "@/lib/framecn-ui";
import type { FramecnTheme } from "@/lib/framecn-ui";

export type ToggleGroupState = string;

export type ToggleGroupSize = "default" | "sm";

export interface ToggleGroupItem {
  value: string;
  label: string;
  icon?: ReactNode;
}

export interface ToggleGroupProps {
  state?: ToggleGroupState;
  style?: ToggleGroupStyle;
  items?: ToggleGroupItem[];
  size?: ToggleGroupSize;
  theme?: Partial<FramecnTheme>;
  align?: "start" | "center" | "end";
  className?: string;
}
const justify = (align: "start" | "center" | "end"): string => {
  if (align === "start") {
    return "flex-start";
  }
  if (align === "end") {
    return "flex-end";
  }
  return "center";
};

const DEFAULT_ITEMS: ToggleGroupItem[] = [
  { label: "Monthly", value: "Monthly" },
  { label: "Yearly", value: "Yearly" },
];
const SIZE_STYLES: Record<
  ToggleGroupSize,
  {
    height: number;
    segMinWidth: number;
    fontSize: number;
    pad: number;
    gap: number;
  }
> = {
  default: { fontSize: 14, gap: 8, height: 36, pad: 0, segMinWidth: 88 },
  sm: { fontSize: 14, gap: 8, height: 32, pad: 0, segMinWidth: 72 },
};

export interface ToggleGroupStyle {
  indicatorOffset: number;
}

export interface ToggleGroupStyleContext {
  items: ToggleGroupItem[];
  trackBg: string;
  thumbBg: string;
  activeFg: string;
  inactiveFg: string;
  radius: number;
}

export const toggleGroupStyleContext = (
  items: ToggleGroupItem[],
  theme: FramecnTheme
): ToggleGroupStyleContext => ({
  activeFg: theme.accentForeground,
  inactiveFg: theme.foreground,
  items,
  radius: Math.max(0, theme.radius - 2),
  thumbBg: theme.accent,
  trackBg: "transparent",
});

export const toggleGroupStyle = (
  state: ToggleGroupState,
  ctx: ToggleGroupStyleContext
): ToggleGroupStyle => {
  const i = ctx.items.findIndex((it) => it.value === state);
  return { indicatorOffset: Math.max(0, i) };
};

export const ToggleGroup = ({
  state = DEFAULT_ITEMS[0].value,
  style,
  items = DEFAULT_ITEMS,
  size = "default",
  theme: themeOverride,
  align = "center",
  className,
}: ToggleGroupProps) => {
  const theme = useFramecnTheme(themeOverride);
  const ctx = toggleGroupStyleContext(items, theme);
  const v = style ?? toggleGroupStyle(state, ctx);
  const sizeStyle = SIZE_STYLES[size];
  const { pad } = sizeStyle;
  const segmentWidth = sizeStyle.segMinWidth;
  const thumbX = pad + v.indicatorOffset * segmentWidth;
  return (
    <div
      className={className}
      style={{
        alignItems: "center",
        background: "transparent",
        display: "flex",
        fontFamily:
          "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
        inset: 0,
        justifyContent: justify(align),
        position: "absolute",
      }}
    >
      <div
        style={{
          background: ctx.trackBg,
          borderRadius: ctx.radius,
          boxSizing: "border-box",
          display: "flex",
          height: sizeStyle.height,
          padding: pad,
          position: "relative",
        }}
      >
        <div
          style={{
            background: ctx.thumbBg,
            borderRadius: ctx.radius,
            height: sizeStyle.height - pad * 2,
            left: thumbX,
            position: "absolute",
            top: pad,
            width: segmentWidth,
          }}
        />

        {items.map((item, i) => {
          const proximity = Math.max(0, 1 - Math.abs(i - v.indicatorOffset));
          return (
            <span
              key={item.value}
              style={{
                alignItems: "center",
                color: mixOklch(ctx.inactiveFg, ctx.activeFg, proximity),
                display: "flex",
                fontSize: sizeStyle.fontSize,
                fontWeight: 500,
                gap: sizeStyle.gap,
                justifyContent: "center",
                lineHeight: "20px",
                position: "relative",
                width: segmentWidth,
              }}
            >
              {item.icon}
              {item.label}
            </span>
          );
        })}
      </div>
    </div>
  );
};

"use client";

import { easings, useFramecnTheme, useStateTransition } from "@/lib/framecn-ui";
import type { FramecnTheme, Step } from "@/lib/framecn-ui";
import {
  toggleGroupStyle,
  toggleGroupStyleContext,
} from "@/components/framecn/toggle-group";
import type {
  ToggleGroupItem,
  ToggleGroupState,
  ToggleGroupStyle,
} from "@/components/framecn/toggle-group";

const DEFAULT_ITEMS: ToggleGroupItem[] = [
  { label: "Monthly", value: "Monthly" },
  { label: "Yearly", value: "Yearly" },
];

export const DEFAULT_DURATION = 14;

export const tweenToggleGroupStyle = (
  a: ToggleGroupStyle,
  b: ToggleGroupStyle,
  t: number
): ToggleGroupStyle => ({
  indicatorOffset:
    a.indicatorOffset + (b.indicatorOffset - a.indicatorOffset) * t,
});

export interface ToggleGroupTransitionOptions {
  items?: ToggleGroupItem[];
  theme?: Partial<FramecnTheme>;
  mode?: "light" | "dark";
  speed?: number;
  defaultDuration?: number;
}

export const useToggleGroupTransition = (
  steps: Step<ToggleGroupState>[],
  opts: ToggleGroupTransitionOptions = {}
): ToggleGroupStyle => {
  const {
    items = DEFAULT_ITEMS,
    theme: themeOverride,
    mode,
    speed = 1,
    defaultDuration = DEFAULT_DURATION,
  } = opts;
  const theme = useFramecnTheme(themeOverride, mode);
  const ctx = toggleGroupStyleContext(items, theme);
  const { from, to, progress } = useStateTransition(
    steps,
    items[0].value,
    speed,
    defaultDuration
  );
  const t = easings.out(progress);
  return tweenToggleGroupStyle(
    toggleGroupStyle(from, ctx),
    toggleGroupStyle(to, ctx),
    t
  );
};
